import hashlib

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm."""
    def decorator(func):
        cache = {}
        freq = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key_parts = (*args,)
            if kwargs:
                # Sort items to make hashable and order independent
                key_parts += tuple(sorted(kwargs.items()))
            if typed:
                key_parts += tuple(type(arg) for arg in args)
                key_parts += tuple(type(value) for value in kwargs.values())
            try:
                key = hashlib.sha256(repr(key_parts).encode()).digest()
            except Exception:
                key = key_parts
            if key in cache:
                freq[key] += 1

