import copy

def difference(d1, d2, level=-1):
    def _diff(a, b, level):
        if not isinstance(a, dict) or not isinstance(b, dict):
            return copy.deepcopy(a)
        diff = {}
        for k, v in a.items():
            if k not in b:
                diff[k] = copy.deepcopy(v)
            else:
                if isinstance(v, dict) and isinstance(b[k], dict):
                    if level == 0:
                        continue
                    subdiff = _diff(v, b[k], level-1 if level>0 else -1)
                    if subdiff:
                        diff[k] = subdiff
                else:
                    if level <=0:
                        continue
                    if v != b[k]:
                        diff[k] = copy.deepcopy(v)
        return diff
    return _diff(d1, d2, level)
```

