def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(obj, level):
        spacer = '  ' * level
        if isinstance(obj, (list, tuple, set)):
            items = [f'{spacer}  { _format(item, level+1)}' for item in obj]
            return f'[{",\n".join(items)}]'
        if isinstance(obj, dict):
            items = [f'{spacer}  {k!r}: { _format(v, level+1)}' for k, v in obj.items()]
            return f'{{\n{",\n".join(items)}\n{spacer}}}'
        if hasattr(obj, '__dict__'):
            return _format(vars(obj), level)
        try:
            return json.dumps(obj, indent=2, default=lambda o: str(o))
        except Exception:
            return str(obj)
    return _format(self, indent)
